/// Render frame enum.
enum BgfxRenderFrame {
  BGFX_RENDER_FRAME_NO_CONTEXT(0),

  /// ( 0) Renderer context is not created yet.
  BGFX_RENDER_FRAME_RENDER(1),

  /// ( 1) Renderer context is created and rendering.
  BGFX_RENDER_FRAME_TIMEOUT(2),

  /// ( 2) Renderer context wait for main thread signal timed out without rendering.
  BGFX_RENDER_FRAME_EXITING(3),

  /// ( 3) Renderer context is getting destroyed.
  BGFX_RENDER_FRAME_COUNT(4);

  final int value;
  const BgfxRenderFrame(this.value);

  static BgfxRenderFrame fromValue(int value) => switch (value) {
    0 => BGFX_RENDER_FRAME_NO_CONTEXT,
    1 => BGFX_RENDER_FRAME_RENDER,
    2 => BGFX_RENDER_FRAME_TIMEOUT,
    3 => BGFX_RENDER_FRAME_EXITING,
    4 => BGFX_RENDER_FRAME_COUNT,
    _ => throw ArgumentError('Unknown value for BgfxRenderFrame: $value'),
  };
}

