/// Fatal error enum.
enum bgfx_fatal {
  BGFX_FATAL_DEBUG_CHECK(0),

  /// ( 0)
  BGFX_FATAL_INVALID_SHADER(1),

  /// ( 1)
  BGFX_FATAL_UNABLE_TO_INITIALIZE(2),

  /// ( 2)
  BGFX_FATAL_UNABLE_TO_CREATE_TEXTURE(3),

  /// ( 3)
  BGFX_FATAL_DEVICE_LOST(4),

  /// ( 4)
  BGFX_FATAL_COUNT(5);

  final int value;
  const bgfx_fatal(this.value);

  static bgfx_fatal fromValue(int value) => switch (value) {
    0 => BGFX_FATAL_DEBUG_CHECK,
    1 => BGFX_FATAL_INVALID_SHADER,
    2 => BGFX_FATAL_UNABLE_TO_INITIALIZE,
    3 => BGFX_FATAL_UNABLE_TO_CREATE_TEXTURE,
    4 => BGFX_FATAL_DEVICE_LOST,
    5 => BGFX_FATAL_COUNT,
    _ => throw ArgumentError('Unknown value for bgfx_fatal: $value'),
  };
}

