/// Configurable runtime limits parameters.
final class bgfx_init_limits_s extends ffi.Struct {
  @ffi.Uint16()
  external int maxEncoders;

  /// Initial number of draw calls per frame. Rounded up to a
  /// multiple of 1024 (the minimum); 0 selects the default of 1024.
  /// The render-item buffers grow on demand up to
  /// `BGFX_CONFIG_MAX_DRAW_CALLS` and lazily shrink.
  @ffi.Uint32()
  external int numDrawCalls;

  /// Number of frames the draw-call peak (high-water mark) is observed
  /// before the render-item buffers are shrunk. Set to 0 to disable
  /// dynamic resizing and keep the buffers fixed at `numDrawCalls`.
  @ffi.Uint32()
  external int numDrawCallPeakFrames;

  @ffi.Uint32()
  external int minResourceCbSize;

  /// Minimum resource command buffer size.
  @ffi.Uint32()
  external int maxTransientVbSize;

  /// Maximum transient vertex buffer size.
  @ffi.Uint32()
  external int maxTransientIbSize;

  /// Maximum transient index buffer size.
  @ffi.Uint32()
  external int minUniformBufferSize;

  static ffi.Pointer<bgfx_init_limits_s> $allocate(
    ffi.Allocator $allocator, {
    required int maxEncoders,
    required int numDrawCalls,
    required int numDrawCallPeakFrames,
    required int minResourceCbSize,
    required int maxTransientVbSize,
    required int maxTransientIbSize,
    required int minUniformBufferSize,
  }) => $allocator<bgfx_init_limits_s>()
    ..ref.maxEncoders = maxEncoders
    ..ref.numDrawCalls = numDrawCalls
    ..ref.numDrawCallPeakFrames = numDrawCallPeakFrames
    ..ref.minResourceCbSize = minResourceCbSize
    ..ref.maxTransientVbSize = maxTransientVbSize
    ..ref.maxTransientIbSize = maxTransientIbSize
    ..ref.minUniformBufferSize = minUniformBufferSize;
}

typedef bgfx_init_limits_t = bgfx_init_limits_s;

/// Initialization parameters used by `bgfx::init`.
final class bgfx_init_s extends ffi.Struct {
  /// Select rendering backend. When set to RendererType::Count
  /// a default rendering backend will be selected appropriate to the platform.
  /// See: `bgfx::RendererType`
  @ffi.UnsignedInt()
  external int typeAsInt;

  bgfx_renderer_type get type => bgfx_renderer_type.fromValue(typeAsInt);
  set type(bgfx_renderer_type value) => typeAsInt = value.value;

  /// Vendor PCI ID. If set to `BGFX_PCI_ID_NONE`, discrete and integrated
  /// GPUs will be prioritised.
  /// - `BGFX_PCI_ID_NONE` - Autoselect adapter.
  /// - `BGFX_PCI_ID_SOFTWARE_RASTERIZER` - Software rasterizer.
  /// - `BGFX_PCI_ID_AMD` - AMD adapter.
  /// - `BGFX_PCI_ID_APPLE` - Apple adapter.
  /// - `BGFX_PCI_ID_INTEL` - Intel adapter.
  /// - `BGFX_PCI_ID_NVIDIA` - NVIDIA adapter.
  /// - `BGFX_PCI_ID_MICROSOFT` - Microsoft adapter.
  @ffi.Uint16()
  external int vendorId;

  /// Device ID. If set to 0 it will select first device, or device with
  /// matching ID.
  @ffi.Uint16()
  external int deviceId;

  @ffi.Uint64()
  external int capabilities;

  /// Capabilities initialization mask (default: UINT64_MAX).
  @ffi.Bool()
  external bool debug;

  /// Enable device for debugging.
  @ffi.Bool()
  external bool profile;

  /// Enable device for profiling.
  @ffi.Bool()
  external bool fallback;

  /// Enable fallback to next available renderer.
  @ffi.Bool()
  external bool videoDecode;

  /// Enable video decoding.
  external bgfx_platform_data_t platformData;

  /// Platform data.
  external bgfx_resolution_t resolution;

  /// Backbuffer resolution and reset parameters. See: `bgfx::Resolution`.
  external bgfx_init_limits_t limits;

  /// Provide application specific callback interface.
  /// See: `bgfx::CallbackI`
  external ffi.Pointer<bgfx_callback_interface_t> callback;

  /// Custom allocator. When a custom allocator is not
  /// specified, bgfx uses the CRT allocator. Bgfx assumes
  /// custom allocator is thread safe.
  external ffi.Pointer<bgfx_allocator_interface_t> allocator;
}

typedef bgfx_init_t = bgfx_init_s;

