  @ffi.Array.multi([256])
  external ffi.Array<ffi.Char> name;

  /// Uniform name.
  @ffi.UnsignedInt()
  external int typeAsInt;

  bgfx_uniform_type get type => bgfx_uniform_type.fromValue(typeAsInt);
  set type(bgfx_uniform_type value) => typeAsInt = value.value;

  /// Uniform type.
  @ffi.Uint16()
  external int num;
}

typedef bgfx_uniform_info_t = bgfx_uniform_info_s;

/// Uniform type enum.
enum bgfx_uniform_type {
  BGFX_UNIFORM_TYPE_SAMPLER(0),

  /// ( 0) Sampler.
  BGFX_UNIFORM_TYPE_END(1),

  /// ( 1) Reserved, do not use.
  BGFX_UNIFORM_TYPE_VEC4(2),

  /// ( 2) 4 floats vector.
  BGFX_UNIFORM_TYPE_MAT3(3),

  /// ( 3) 3x3 matrix.
  BGFX_UNIFORM_TYPE_MAT4(4),

  /// ( 4) 4x4 matrix.
  BGFX_UNIFORM_TYPE_COUNT(5);

  final int value;
  const bgfx_uniform_type(this.value);

  static bgfx_uniform_type fromValue(int value) => switch (value) {
    0 => BGFX_UNIFORM_TYPE_SAMPLER,
    1 => BGFX_UNIFORM_TYPE_END,
    2 => BGFX_UNIFORM_TYPE_VEC4,
    3 => BGFX_UNIFORM_TYPE_MAT3,
    4 => BGFX_UNIFORM_TYPE_MAT4,
    5 => BGFX_UNIFORM_TYPE_COUNT,
    _ => throw ArgumentError('Unknown value for bgfx_uniform_type: $value'),
  };
}

