typedef bgfx_vertex_layout_handle_t = bgfx_vertex_layout_handle_s;

/// Vertex layout.
final class bgfx_vertex_layout_s extends ffi.Struct {
  @ffi.Uint32()
  external int hash;

  /// Hash.
  @ffi.Uint16()
