typedef bgfx_vertex_layout_t = bgfx_vertex_layout_s;

/// Video codec enum.
enum bgfx_video_codec {
  BGFX_VIDEO_CODEC_H264(0),

  /// ( 0) H.264 / AVC.
  BGFX_VIDEO_CODEC_H265(1),

  /// ( 1) H.265 / HEVC.
  BGFX_VIDEO_CODEC_AV1(2),

  /// ( 2) AV1.
  BGFX_VIDEO_CODEC_COUNT(3);

  final int value;
  const bgfx_video_codec(this.value);

  static bgfx_video_codec fromValue(int value) => switch (value) {
    0 => BGFX_VIDEO_CODEC_H264,
    1 => BGFX_VIDEO_CODEC_H265,
    2 => BGFX_VIDEO_CODEC_AV1,
    3 => BGFX_VIDEO_CODEC_COUNT,
    _ => throw ArgumentError('Unknown value for bgfx_video_codec: $value'),
  };
}

/// One access unit entry inside a `VideoDecoderFrame` batch. The bitstream
/// for the AU lives at offset `Σ aus[0..ii].size` inside the frame's
/// `bitstream` buffer (access units are stored back-to-back in decode /
/// submission order).
final class bgfx_video_decoder_au_s extends ffi.Struct {
  @ffi.Uint32()
  external int size;

  /// Access unit size in bytes.
  @ffi.Int64()
  external int ptsUs;

  static ffi.Pointer<bgfx_video_decoder_au_s> $allocate(
    ffi.Allocator $allocator, {
    required int size,
    required int ptsUs,
  }) => $allocator<bgfx_video_decoder_au_s>()
    ..ref.size = size
    ..ref.ptsUs = ptsUs;
}

typedef bgfx_video_decoder_au_t = bgfx_video_decoder_au_s;

/// Video decoder per-frame submission. Serialized into the Memory passed
/// to `updateTexture2D` for a video decode destination texture. The
/// renderer parses the slice / tile-group header out of the bitstream and
/// translates it to the backend-specific decoder arguments.
///
/// A single call may submit a batch of access units: `bitstream` is the
/// back-to-back concatenation of `numAus` access units, and `aus[ii]`
/// holds the size and PTS of each. AUs are enqueued in array order
/// (which is the codec's decode order). Set `numAus == 0` (and
/// `bitstream == NULL`) for a presentation-only tick that only advances
/// the playback clock.
///
/// The `bitstream` and `aus` pointers must remain valid until bgfx has
/// consumed the submission (`bgfx::copy` only deep-copies the
/// `VideoDecoderFrame` struct itself, not the buffers it references).
final class bgfx_video_decoder_frame_s extends ffi.Struct {
  @ffi.Uint32()
  external int magic;

  /// Structure magic. Must be `BX_MAKEFOURCC('V', 'D', 'F', 0x0)`.
  external ffi.Pointer<ffi.Uint8> bitstream;

  /// Concatenated access-unit bitstream (decode order). NULL for presentation-only ticks.
  external ffi.Pointer<bgfx_video_decoder_au_t> aus;

  /// Per-AU size and PTS array. NULL when `numAus == 0`.
  @ffi.Uint32()
  external int numAus;

  /// Current playback wall-clock time. Driver dispatches the picture whose `ptsUs`
  /// best matches. Must be monotonically non-decreasing between non-`SET` calls.
  @ffi.Int64()
  external int presentationTimeUs;

  @ffi.Uint8()
  external int flags;

  static ffi.Pointer<bgfx_video_decoder_frame_s> $allocate(
    ffi.Allocator $allocator, {
    required int magic,
    required ffi.Pointer<ffi.Uint8> bitstream,
    required ffi.Pointer<bgfx_video_decoder_au_t> aus,
    required int numAus,
    required int presentationTimeUs,
    required int flags,
  }) => $allocator<bgfx_video_decoder_frame_s>()
    ..ref.magic = magic
    ..ref.bitstream = bitstream
    ..ref.aus = aus
    ..ref.numAus = numAus
    ..ref.presentationTimeUs = presentationTimeUs
    ..ref.flags = flags;
}

typedef bgfx_video_decoder_frame_t = bgfx_video_decoder_frame_s;

/// Video decoder initialization. Serialized into the Memory passed to
/// `createTexture2D`. When the memory blob begins with `magic`, bgfx
/// infers the texture is a video decode destination (the caller need not set
/// any extra texture flag). Everything else the renderer needs about the
/// stream (chroma format, bit depth, profile, level, coded dimensions, DPB
/// layout, color metadata) is parsed out of the codec parameter sets at
/// create time.
final class bgfx_video_decoder_init_s extends ffi.Struct {
  @ffi.Uint32()
  external int magic;

  /// Structure magic. Must be `BX_MAKEFOURCC('V', 'D', 'I', 0x0)`.
  @ffi.UnsignedInt()
  external int codecAsInt;

  bgfx_video_codec get codec => bgfx_video_codec.fromValue(codecAsInt);
  set codec(bgfx_video_codec value) => codecAsInt = value.value;

  /// Video codec. See: `VideoCodec::Enum`.
  external ffi.Pointer<ffi.Uint8> parameterSets;

  /// Codec parameter sets (Annex B for H.264/H.265, OBUs for AV1).
  @ffi.Uint32()
  external int parameterSetsSize;

  /// Soft cap (in bytes) on the streaming access-unit FIFO (when
  /// `BGFX_VIDEO_DECODER_INIT_RETAIN` is NOT set). 0 selects the
  /// default. Ignored in RETAIN mode (the retain cache is unbounded).
  @ffi.Uint32()
  external int cachedAuBytes;

  @ffi.Uint8()
  external int flags;

  static ffi.Pointer<bgfx_video_decoder_init_s> $allocate(
    ffi.Allocator $allocator, {
    required int magic,
    required bgfx_video_codec codec,
    required ffi.Pointer<ffi.Uint8> parameterSets,
    required int parameterSetsSize,
    required int cachedAuBytes,
    required int flags,
  }) => $allocator<bgfx_video_decoder_init_s>()
    ..ref.magic = magic
    ..ref.codec = codec
    ..ref.parameterSets = parameterSets
    ..ref.parameterSetsSize = parameterSetsSize
    ..ref.cachedAuBytes = cachedAuBytes
    ..ref.flags = flags;
}

typedef bgfx_video_decoder_init_t = bgfx_video_decoder_init_s;

/// /
typedef bgfx_view_id_t = ffi.Uint16;
typedef Dartbgfx_view_id_t = int;

/// View mode sets draw call sort order.
enum bgfx_view_mode {
  BGFX_VIEW_MODE_DEFAULT(0),

  /// ( 0) Default sort order.
  BGFX_VIEW_MODE_SEQUENTIAL(1),

  /// ( 1) Sort in the same order in which submit calls were called.
  BGFX_VIEW_MODE_DEPTH_ASCENDING(2),

  /// ( 2) Sort draw call depth in ascending order.
  BGFX_VIEW_MODE_DEPTH_DESCENDING(3),

  /// ( 3) Sort draw call depth in descending order.
  BGFX_VIEW_MODE_COUNT(4);

  final int value;
  const bgfx_view_mode(this.value);

  static bgfx_view_mode fromValue(int value) => switch (value) {
    0 => BGFX_VIEW_MODE_DEFAULT,
    1 => BGFX_VIEW_MODE_SEQUENTIAL,
    2 => BGFX_VIEW_MODE_DEPTH_ASCENDING,
    3 => BGFX_VIEW_MODE_DEPTH_DESCENDING,
    4 => BGFX_VIEW_MODE_COUNT,
    _ => throw ArgumentError('Unknown value for bgfx_view_mode: $value'),
  };
}

/// View stats.
final class bgfx_view_stats_s extends ffi.Struct {
  @ffi.Array.multi([256])
  external ffi.Array<ffi.Char> name;

  /// View name.
  @bgfx_view_id_t()
  external int view;

  /// View id.
  @ffi.Int64()
  external int cpuTimeBegin;

  /// CPU (submit) begin time.
  @ffi.Int64()
  external int cpuTimeEnd;

  /// CPU (submit) end time.
  @ffi.Int64()
  external int gpuTimeBegin;

  /// GPU begin time.
  @ffi.Int64()
  external int gpuTimeEnd;

  /// GPU end time.
  @ffi.Uint32()
  external int gpuFrameNum;
}

typedef bgfx_view_stats_t = bgfx_view_stats_s;
